import { useEffect, useState } from "react";

export type DefaultMap = Record<string, unknown>;

export const useOptions = <T extends DefaultMap>(
  initial: T,
  {
    set: setCb,
    wrap: wrapCb,
  }: {
    /** Callback for when a value is set.
     * It is important you do not call set within this callback
     * */
    set?: <K extends keyof T>(
      p: { key: K; value: T[K]; newState: T } | { key: undefined; value: undefined; newState: T }
    ) => void;
    /** If a set is called, you can pass a wrapper to pipe the new state before it is committed */
    wrap?: <K extends keyof T>(p: { key: K; value: T[K]; state: T; newState: T }) => T;
  } = {}
) => {
  type OptionKey = keyof typeof options;
  type OptionVal<K extends OptionKey> = (typeof options)[K];
  const [options, _setOptions] = useState<T>(initial);

  // TODO: Compare fn
  const dirty = Object.entries(options).some(([k, v]) => initial[k] !== v);

  useEffect(() => {
    initial && setCb?.({ newState: initial, key: undefined, value: undefined });
  }, []);

  // [claude@2026-04-23] Compute next state from a given previous snapshot, applying wrap.
  // Returns a fresh object each call so wrap callbacks that mutate their `newState` arg
  // (see image-recolor.module.tsx) don't cross-contaminate between invocations.
  const _computeNext = <K extends OptionKey>(prev: T, key: K, value: OptionVal<K>): T => {
    let newState: T = { ...prev, [key]: value };
    if (wrapCb) newState = wrapCb({ key, value, state: prev, newState });
    return newState;
  };

  // [claude@2026-04-23] State update uses React's functional form so multiple synchronous
  // `.set(key, v)` calls on different keys don't stale-overwrite each other (useQSync
  // hydrates several keys in one tick). setCb still fires with a captured-snapshot
  // newState — preserves existing caller contract where each call reports one key's intent.
  const _setOption = <K extends OptionKey>(key: K, value: OptionVal<K>) => {
    _setOptions((prev) => _computeNext(prev, key, value));
    if (setCb) setCb({ key, value, newState: _computeNext(options, key, value) });
  };

  const _setOptionCb =
    <K extends OptionKey>(key: K) =>
    (value: OptionVal<K>) =>
      _setOption(key, value);

  const _resetOption = <K extends OptionKey>(key: K) => {
    _setOption(key, initial?.[key]);
  };

  const _resetAll = () => {
    _setOptions(initial);
  };

  const optionSetter = {
    /** Set a single key */
    set: _setOption,
    /** Callback for setting a value given a key */
    setCb: _setOptionCb,
    /** Reset a given option to initial */
    reset: _resetOption,
    /** Set the whole object */
    setAll: _setOptions,
    /** Reset the whole object */
    resetAll: _resetAll,
  };

  return [options, optionSetter, { dirty }] as const;
};

export type UseOptionsReturn<T extends DefaultMap> = ReturnType<typeof useOptions<T>>;
export type UpdateOption<T extends DefaultMap> = UseOptionsReturn<T>[1];

