/** Hook for fetching a job's output preview (rows + metadata) with status-filter / tab / fab options. Co-located with the small types it owns. */

import { formatJobOutputError } from "@/app/jobs/(list)/utils/job-output.errors";
import type { AppliedJobConfigMap, JobStatus, LocalJobStatus } from "@/app/jobs/jobs.types";
import type { FabOptions } from "@/app/templates/new-template/upload/upload.utils";
import type { JobOutputResponse, JobOutputSettings } from "@/data/jobs.data";
import { getJobOutput, getJobOutputPost, MaxJobPreviewRowLimit } from "@/data/jobs.data";
import { groupRowsByStatus, type JobItemStatus } from "@/data/jobs/status";
import type { DataRow } from "@/data/pipeline/pipeline.types";
import { useQ } from "@/utils/hooks/use-q";
import { QueryKeys } from "@/utils/react-query";
import type { QueryObserverOptions } from "@tanstack/react-query";
import { keepPreviousData } from "@tanstack/react-query";
import { useEffect, useMemo, useState } from "react";

// export const ItemStatusIcons = {} satisfies Record<JobItemStatus, IconKeys>;

type JobOutputQueryResponse = {
  data: JobOutputResponse.PreviewWithMetadata;
  metadata: {
    total: number;
    limit: number;
    skip: number;
    contentType: string;
    s3Url: string;
    s3UrlExpires: string | number;
    outputFileTabs: string[];
    dataSource: "custom" | "external_file" | "job" | "unknown";
  };
};

const DefaultTab = "__DefaultTab__";

export const useJobOutput = ({
  jobId,
  customItems,
  initialDisabled = false,
  customJobConfig,
  observerOptions,
  outputSettings,
  // Drives per-row status derivation. Defaults so callers that don't show the
  // status filter (e.g. the validation preview) need not pass it.
  jobStatus = "pending",
}: {
  jobId: string;
  customItems?: DataRow[];
  customJobConfig?: AppliedJobConfigMap;
  initialDisabled?: boolean;
  observerOptions?: Partial<QueryObserverOptions<JobOutputQueryResponse>>;
  outputSettings?: JobOutputSettings;
  jobStatus?: JobStatus | LocalJobStatus;
}) => {
  const [itemStatusFilter, setItemStatusFilter] = useState<JobItemStatus[]>([]);
  const [tabToShow, setTabToShow] = useState<string>(DefaultTab);

  const [fabOptions, setFabOptions] = useState<FabOptions>({
    mode: "delimiter",
    delimiter: "number",
  });

  const options = {
    itemStatusFilter,
    tabToShow: tabToShow ?? DefaultTab,
    fabOptions,
  };

  const setOptions = {
    setItemStatusFilter,
    setTabToShow,
    setFabOptions,
  };

  const queryKey = QueryKeys.GetJobOutput(jobId).concat(
    options.fabOptions.mode,
    options.fabOptions.delimiter || "number",
    options.tabToShow || "default-tab"
  );

  const fn = useMemo(() => (customItems?.length ? getJobOutputPost : getJobOutput), [customItems?.length]);

  const {
    data: outputResponse,
    isLoading,
    isFetching,
    isPending,
    refetch: refetchOutput,
    dataUpdatedAt,
  } = useQ({
    staleTime: 5_000,
    error: {
      toast: {
        // Render the backend's structured JobOutputError envelope into a user-facing
        // sentence; fall back to the generic API error for non-job-output failures.
        message: (err) => formatJobOutputError(err, `Couldn't load preview for this job. Please try again.`),
        options: {
          duration: -1,
        },
      },
    },
    placeholderData: keepPreviousData,
    enabled: !initialDisabled,
    queryKey,
    ...observerOptions,

    queryFn: async () =>
      await fn<JobOutputResponse.PreviewWithMetadata>({
        jobId,
        args: {
          custom_items: customItems,
          custom_job_config_data: customJobConfig,
          // Fetch all items once, filter locally for snappier UX.
          additionalQueryParams: tabToShow && tabToShow !== DefaultTab ? { file_tab: tabToShow } : {},
          output_settings: {
            fallback_input_values: true,
            include_metadata: true,
            fab_options: fabOptions,
            items_skip: 0,
            items_limit: MaxJobPreviewRowLimit,
            ...outputSettings,
          },
          paginationQueryParams: {
            // Local pagination — file rows < 5k. Revisit if perf becomes an issue.
            return_all: false,
          },
        },
      }).then(({ data = [], metadata, ...resp }) => ({
        ...resp,
        data: data,
        metadata: {
          total: metadata.total ?? 100,
          limit: metadata.limit ?? 10,
          skip: metadata.skip ?? 0,
          contentType: metadata.contentType ?? "application/json",
          s3Url: metadata.s3Url ?? "",
          s3UrlExpires: metadata.s3UrlExpires ?? 0,
          outputFileTabs: (metadata.outputFileTabs || "").split(";") || [],
          dataSource: metadata.dataSource || "unknown",
          transformFns: metadata.transformFns || [],
        },
      })),
  });

  const {
    outputRows = [],
    metadata,
    allRows = [],
    statusCounts,
  } = useMemo(() => {
    const allRows = outputResponse?.data ?? [];
    // One pass over all rows: derive each row's real status, count per status,
    // and slice the active filter — replaces the old processed-boolean split.
    const { rowStatus, counts } = groupRowsByStatus(allRows, jobStatus);
    const rows =
      itemStatusFilter.length === 0
        ? allRows
        : allRows.filter((r) => rowStatus.get(r) && itemStatusFilter.includes(rowStatus.get(r)!));
    return {
      outputRows: rows,
      allRows,
      statusCounts: counts,
      metadata: outputResponse?.metadata ?? {
        total: 100,
        limit: 10,
        skip: 0,
        contentType: "application/json",
        outputFileTabs: [],
        dataSource: "unknown",
      },
    };
  }, [outputResponse, itemStatusFilter, jobStatus]);

  // Auto-select the first tab once tab metadata arrives.
  useEffect(() => {
    if (tabToShow) return;
    if (!metadata?.outputFileTabs?.length) return;
    console.log("setTabToShow", metadata?.outputFileTabs?.[0]);
    setTabToShow(metadata.outputFileTabs[0] ?? DefaultTab);
  }, [metadata?.outputFileTabs, tabToShow]);

  return {
    data: {
      outputRows,
      metadata,
      allRows,
      statusCounts,
      refetchOutput,
    },
    flags: {
      isLoading,
      isFetching,
      isPending,
      dataUpdatedAt,
    },
    options,
    setOptions,
  };
};

