1	import type { AlertToast } from "@/core/toast-provider/toast-context";
2	import { useAlertToast } from "@/core/toast-provider/toast-context";
3	import { getApiError } from "@/utils/error";
4	
5	import { authInitializedAtom, authValidAtom } from "@/core/app-init.utils";
6	
7	import type { QueryKey, UseQueryOptions, UseQueryResult } from "@tanstack/react-query";
8	// eslint-disable-next-line no-restricted-syntax, no-restricted-imports
9	import { useQuery } from "@tanstack/react-query";
10	import { AxiosError } from "axios";
11	import { useAtomValue } from "jotai";
12	import { useEffect, useMemo } from "react";
13	import { isDevelopment } from "../core/flags";
14	import { useAuthToken } from "./use-auth-token";
15	
16	const NewDeploymentId = "new-deployment";
17	export const ApiUnreachableId = "api-unreachable";
18	const b = Boolean;
19	export const useQ = <
20	  TQueryFnData = unknown,
21	  TError = AxiosError,
22	  TData = TQueryFnData,
23	  TQueryKey extends QueryKey = QueryKey,
24	>({
25	  isPending: getIsPending,
26	  error: errorProps,
27	  ...userOptions
28	}: Omit<UseQueryOptions<TQueryFnData, TError, TData, TQueryKey>, "queryKey"> & {
29	  queryKey: TQueryKey;
30	} & {
31	  isPending?: (v: boolean, qResponse: Omit<UseQueryResult<TData, TError>, "isPending">) => boolean;
32	  error?: {
33	    callback?: (error: TError) => void;
34	    toast?: {
35	      disabled?: boolean;
36	      message?: (error: TError) => string;
37	      variant?: AlertToast["variant"];
38	      options?: AlertToast["options"];
39	    };
40	  };
41	}) => {
42	  const { token } = useAuthToken();
43	  const { pushAlert, removeAlert } = useAlertToast();
44	  const authValid = useAtomValue(authValidAtom);
45	  const authInitialized = useAtomValue(authInitializedAtom);
46	  // const { isApiReachable } = useConnectivityStatus();
47	
48	  const isEnabled =
49	    authInitialized &&
50	    b(b(("enabled" in userOptions ? userOptions.enabled : true) && token && !!authValid) || b(userOptions.initialData));
51	
52	  // TODO: Use https://usehooks.com/usenetworkstate
53	  const qResponse = useQuery<TQueryFnData, TError, TData, TQueryKey>({
54	    staleTime: 5 * 60 * 1000, // 5 minutes
55	    refetchInterval: 10_000, // 10 seconds
56	    refetchOnMount: true,
57	    ...userOptions,
58	    enabled: isEnabled,
59	    // Only 1 retry by default if in development mode
60	    retry: userOptions.retry ?? (isDevelopment ? 1 : undefined),
61	    // If initial data is present, auto-fill the defaults for `refetchOnMount` and `initialDataUpdatedAt`
62	    // initialData: userOptions?.initialData,
63	    // refetchOnMount: userOptions.refetchOnMount || !!userOptions?.initialData,
64	    // initialDataUpdatedAt: userOptions.initialDataUpdatedAt || (!!userOptions?.initialData ? Date.now() : undefined),
65	  });
66	
67	  const isPending = getIsPending?.(qResponse.isPending, qResponse) ?? qResponse.isPending;
68	  const qKey = useMemo(() => userOptions.queryKey.join("-"), [userOptions.queryKey.join("-")]);
69	
70	  useEffect(() => {
71	    let qErrKey = `q-error-${qKey}`;
72	    if (qResponse.error) {
73	      // Reload data
74	      if (
75	        qResponse.error instanceof Error &&
76	        qResponse?.error?.message?.includes?.("https://nextjs.org/docs/messages/failed-to-find-server-action")
77	      ) {
78	        pushAlert.warning("A new version of the app has been deployed, reloading the page to refresh data.", {
79	          id: NewDeploymentId,
80	          duration: -1,
81	        });
82	        setTimeout(() => {
83	          window.location.reload();
84	        }, 1000);
85	        return;
86	      }
87	      const { toast, callback } = errorProps ?? {};
88	      if (authValid && !toast?.disabled) {
89	        let message = toast?.message
90	          ? toast.message(qResponse.error)
91	          : "Error fetching data: " + getApiError(qResponse.error, `for ${qKey}`);
92	
93	        if (qResponse.error instanceof AxiosError && qResponse.error.code === "ERR_NETWORK") {
94	          // In Chrome, this usually means connection refused
95	          if (qResponse.error.message.includes("Network Error")) {
96	            message = `[API Unreachable] ${message}`;
97	            qErrKey = ApiUnreachableId;
