import type { AlertToast } from "@/core/toast-provider/toast-context";
import { useAlertToast } from "@/core/toast-provider/toast-context";
import { getApiError } from "@/utils/error";

import { authInitializedAtom, authValidAtom } from "@/core/app-init.utils";

import type { QueryKey, UseQueryOptions, UseQueryResult } from "@tanstack/react-query";
// eslint-disable-next-line no-restricted-syntax, no-restricted-imports
import { useQuery } from "@tanstack/react-query";
import { AxiosError } from "axios";
import { useAtomValue } from "jotai";
import { useEffect, useMemo } from "react";
import { isDevelopment } from "../core/flags";
import { useAuthToken } from "./use-auth-token";

const NewDeploymentId = "new-deployment";
export const ApiUnreachableId = "api-unreachable";
const b = Boolean;
export const useQ = <
  TQueryFnData = unknown,
  TError = AxiosError,
  TData = TQueryFnData,
  TQueryKey extends QueryKey = QueryKey,
>({
  isPending: getIsPending,
  error: errorProps,
  ...userOptions
}: Omit<UseQueryOptions<TQueryFnData, TError, TData, TQueryKey>, "queryKey"> & {
  queryKey: TQueryKey;
} & {
  isPending?: (v: boolean, qResponse: Omit<UseQueryResult<TData, TError>, "isPending">) => boolean;
  error?: {
    callback?: (error: TError) => void;
    toast?: {
      disabled?: boolean;
      message?: (error: TError) => string;
      variant?: AlertToast["variant"];
      options?: AlertToast["options"];
    };
  };
}) => {
  const { token } = useAuthToken();
  const { pushAlert, removeAlert } = useAlertToast();
  const authValid = useAtomValue(authValidAtom);
  const authInitialized = useAtomValue(authInitializedAtom);
  // const { isApiReachable } = useConnectivityStatus();

  const isEnabled =
    authInitialized &&
    b(b(("enabled" in userOptions ? userOptions.enabled : true) && token && !!authValid) || b(userOptions.initialData));

  // TODO: Use https://usehooks.com/usenetworkstate
  const qResponse = useQuery<TQueryFnData, TError, TData, TQueryKey>({
    staleTime: 5 * 60 * 1000, // 5 minutes
    refetchInterval: 10_000, // 10 seconds
    refetchOnMount: true,
    ...userOptions,
    enabled: isEnabled,
    // Only 1 retry by default if in development mode
    retry: userOptions.retry ?? (isDevelopment ? 1 : undefined),
    // If initial data is present, auto-fill the defaults for `refetchOnMount` and `initialDataUpdatedAt`
    // initialData: userOptions?.initialData,
    // refetchOnMount: userOptions.refetchOnMount || !!userOptions?.initialData,
    // initialDataUpdatedAt: userOptions.initialDataUpdatedAt || (!!userOptions?.initialData ? Date.now() : undefined),
  });

  const isPending = getIsPending?.(qResponse.isPending, qResponse) ?? qResponse.isPending;
  const qKey = useMemo(() => userOptions.queryKey.join("-"), [userOptions.queryKey.join("-")]);

  useEffect(() => {
    let qErrKey = `q-error-${qKey}`;
    if (qResponse.error) {
      // Reload data
      if (
        qResponse.error instanceof Error &&
        qResponse?.error?.message?.includes?.("https://nextjs.org/docs/messages/failed-to-find-server-action")
      ) {
        pushAlert.warning("A new version of the app has been deployed, reloading the page to refresh data.", {
          id: NewDeploymentId,
          duration: -1,
        });
        setTimeout(() => {
          window.location.reload();
        }, 1000);
        return;
      }
      const { toast, callback } = errorProps ?? {};
      if (authValid && !toast?.disabled) {
        let message = toast?.message
          ? toast.message(qResponse.error)
          : "Error fetching data: " + getApiError(qResponse.error, `for ${qKey}`);

        if (qResponse.error instanceof AxiosError && qResponse.error.code === "ERR_NETWORK") {
          // In Chrome, this usually means connection refused
          if (qResponse.error.message.includes("Network Error")) {
            message = `[API Unreachable] ${message}`;
            qErrKey = ApiUnreachableId;
          }
        }
        pushAlert(toast?.variant ?? "error", message, {
          id: qErrKey,
          duration: 10_000,
          ...toast?.options,
        });
      }
      // If invalid, clear any previous toast because the user is about to be signed out
      if (!authValid) {
        removeAlert(qErrKey);
      }
      if (callback) {
        callback(qResponse.error);
      }
    }
  }, [qResponse.error, errorProps?.toast, authValid, qKey]);

  return { ...qResponse, isPending, data: (qResponse.data || userOptions.initialData) as TData };
};

// TODO: useM

