      `Format: ${v.mode === "delimiter" ? `${FabDelimiters?.[v.delimiter!]?.label || v.delimiter}` : capitalizeAll(v.mode, "_")}`,
    Icon: "FormatRowArrows",
    focusMode: "click",
  } satisfies AppliedFilter<FabOptions>,
  expandRows: {
    value: options.expandCells,
    onChange: (v) => setOptions("expandCells", v),
    clear: () => setOptions("expandCells", false),
    active: (v) => !!v,
    getLabel: (v) => (!v ? "" : "Cells Expanded"),
    Icon: "Expand",
    // focusMode: "click",
  } satisfies AppliedFilter<boolean>,
  showMetadata: {
    value: options.showMetadataCols,
    onChange: (v) => setOptions("showMetadataCols", !v),
    clear: () => setOptions("showMetadataCols", false),
    active: (v) => !!v,
    getLabel: (v) => (!v ? "" : "Show $metadata"),
    Icon: "DollarView",
