  } satisfies AppliedFilter<boolean>,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
} satisfies Record<string, AppliedFilter<any>>;

type FilterId = keyof typeof appliedFilters;
const getControlId = (key: FilterId) => `${key as FilterId}-control`;

const appliedFilterState = useMemo(() => {
  return (
    Object.entries(appliedFilters)
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .filter(([, { value, active }]: [string, AppliedFilter<any>]) => !!active(value))
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .map(([key, { value, getLabel: label, Icon, clear, focusMode }]: [string, AppliedFilter<any>]) => ({
        key,
        value,
        clear,
        label: label(value),
        Icon,
        focus: !focusMode
          ? undefined
          : () => {
              const id = "#" + getControlId(key as FilterId);
              const el = document.querySelector<HTMLElement>(id);
              if (!el) {
                console.warn(`Toolbar control ${el} not found for ${key}`);
                return;
              }
              if (focusMode) el?.[focusMode]();
            },
      }))
  );
}, [appliedFilters]);

