/** Client-side toolbar state for the job-output modal, and the chip registry built from it. */

import type { FabOptions } from "@/app/templates/new-template/upload/upload.utils";
import { FabDelimiters } from "@/app/templates/new-template/upload/upload.utils";
import type { JobItemStatus } from "@/data/jobs/status";
import type { IconRender } from "@/utils/icons";
import { capitalizeAll, pluralize } from "@/utils/text";
import { useReducer } from "react";

export type OutputViewState = {
  search: string;
  columnsToSearch: string[];
  hiddenColumns: Record<string, string[]>; // keyed per sheet
  status: JobItemStatus[];
  expandCells: boolean;
  showMetadataCols: boolean;
  showFabOptions: boolean;
};

const initialViewState: OutputViewState = {
  search: "",
  columnsToSearch: [],
  hiddenColumns: {},
  status: [],
  expandCells: false,
  showMetadataCols: false,
  showFabOptions: false,
};

// Merge-patch reducer so dispatch is stable across renders — descriptors built
// from it can be memoized later without re-plumbing.
export const useOutputViewState = (seed?: Partial<OutputViewState>) =>
  useReducer((state: OutputViewState, patch: Partial<OutputViewState>) => ({ ...state, ...patch }), {
    ...initialViewState,
    ...seed,
  });

export type SetOutputView = (patch: Partial<OutputViewState>) => void;

export type ToolbarControl = {
  id: string;
  active: boolean;
  chip: boolean; // shows as a chip when active
  label: string;
  Icon: IconRender;
  clear: () => void;
  focusMode?: "click" | "focus"; // chip click → focus/open the source control
};

export const buildOutputControls = ({
  view,
  setView,
  fabOptions,
  setFabOptions,
  activeSheet,
}: {
  view: OutputViewState;
  setView: SetOutputView;
  fabOptions: FabOptions;
  setFabOptions: (next: FabOptions) => void;
  activeSheet: string;
}): ToolbarControl[] => {
  const hiddenHere = view.hiddenColumns[activeSheet] ?? [];
  return [
    {
      id: "search",
      active: !!view.search.length,
      chip: true,
      label: `"${view.search}"`,
      Icon: "SearchLight",
      clear: () => setView({ search: "" }),
      focusMode: "focus",
    },
    {
      id: "columnsToSearch",
      active: view.columnsToSearch.length > 0,
      chip: true,
      label: `Search columns: ${view.columnsToSearch.join(", ")}`,
      Icon: "SearchInRows",
      clear: () => setView({ columnsToSearch: [] }),
      focusMode: "click",
    },
    {
      id: "columnsToHide",
      active: hiddenHere.length > 0,
      chip: true,
      label: `${hiddenHere.length} ${pluralize(hiddenHere.length, "column")} hidden`,
      Icon: "Columns",
      clear: () => setView({ hiddenColumns: { ...view.hiddenColumns, [activeSheet]: [] } }),
      focusMode: "click",
    },
    {
      id: "status",
      active: view.status.length > 0,
      chip: true,
      label: `Status: ${view.status.join(", ")}`,
      Icon: "Filter",
      clear: () => setView({ status: [] }),
      focusMode: "click",
    },
    {
      id: "format",
      active: view.showFabOptions,
      chip: true,
      label: `Format: ${
        fabOptions.mode === "delimiter"
          ? FabDelimiters?.[fabOptions.delimiter!]?.label || fabOptions.delimiter
          : capitalizeAll(fabOptions.mode, "_")
      }`,
      Icon: "FormatRowArrows",
      clear: () => {
        setView({ showFabOptions: false });
        setFabOptions({ mode: "delimiter", delimiter: "comma" });
      },
      focusMode: "click",
    },
    {
      id: "expandCells",
      active: view.expandCells,
      chip: true,
      label: "Cells Expanded",
      Icon: "Expand",
      clear: () => setView({ expandCells: false }),
    },
    {
      id: "showMetadataCols",
      active: view.showMetadataCols,
      chip: true,
      label: "Show $metadata",
      Icon: "DollarView",
      clear: () => setView({ showMetadataCols: false }),
    },
  ];
};

export const toChips = (controls: ToolbarControl[]) => controls.filter((c) => c.chip && c.active);

